    "solutionArea": "Acute Care",
    "contentGuide": "Acute Care",
    "status": "PRODUCTION",
    "evoke": "OPENCHART",
    "purpose": "Joint Commission and CMS require any patient restrained for violent behavior or placed in seclusion have a ‘Restraint Face to Face Evaluation’ performed within one hour after restraints have been initiated. An open chart alert will prompt the provider to complete the assessment or allow the provider to document an override reason. Hospital policy and procedures should address who is considered qualified to perform a Restraint Face to Face evaluation. When a trained RN or PA conducts the required face-to-face evaluation, he or she must consult the attending physician or other LIP responsible for the patient’s care as soon as possible after the completion of the evaluation. Hospital policy should address the expected time frame for and the components of the consultation with the attending physician or other LIP consistent.",
    "alertText": "ALERT: @PATIENT:{patInfo} has an order for violent restraints. Please complete the regulatory requirement for a 'Restraint Face to Face Evaluation'. You must click 'Document' below to complete the Face to Face Evaluation.",
