    "status": "PRODUCTION",
    "evoke": "ORDER_EVENT",
    "purpose": "This rule is needed to Alert of patient at risk for 30 day readmission.",
    "alertText": "MESSENGER: @PATIENT:1 in room @PTROOMENC:1 has been identified as a readmission risk during this encounter and has an order to be discharged from the hospital. According to documentation, portions of the patient’s discharge follow up documentation have not been completed. Complete the Depart Process and/or document that a follow up appointment has been arranged for this patient if not already done. Please schedule a follow up appointment within the next 24 hours. NOTIFY: This patient has been identified as a readmission risk during this encounter and has an order to be discharged from the hospital. According to documentation, portions of the patient’s discharge follow up documentation have not been completed. Complete the Depart Process and/or document that a follow up appointment has been arranged for this patient if not already done. Please schedule a follow up appointment within the next 24 hours.",
    "supplementalFiles": "",
