    "purpose": "Alert appears when a patient’s chart is opened by users in Physician positions (except for the “Physician – Emergency Medicine” position) to prompt the provider to complete a certification PowerForm satisfying the two-midnight rule if the form has not already been completed. The rule pairs with the PSO_INPT_CERTIFICATION rule to accomodate for workflows when the PSO Admit to Inpatient order is placed by an Emergency provider, or if the patient's insurance is changed to Medicare/Medicare Advantage after being admitted. Alert displays when the patient’s encounter type is “Inpatient”, the patient’s insurance is “Medicare” or “Medicare Advantage”, the order “PSO Admit to Inpatient” is active on the patient’s chart, there isn’t an “Inpatient Certification” form documented on the encounter. The Certification Form flexes when the requested location is “Behavioral Health” and/or the patient’s facility is a Critical Access Hospital",
    "alertText": "ALERT: @patient:{Encounter} needs a certification form documented. Please click on the 'Certification' button below to access the Inpatient Certification PowerForm, verify all documentation is correct, and sign. If you are not the Admitting or Attending physician, please disregard by selecting Dismiss.",
